function IdolLive3D_FreeCameraTrackNodeParamsManager:__init( name_, jsonData_ )
    self.trackNodeParams = {}
    self.trackNodePitchTans = {} -- {pitchTan,t}[]
    self.name = name_

    assert( isNotNull(jsonData_)  )
    assert( isNotNull(jsonData_.vcamPesists) )

    -- ======================= 补完 freeTrackJson ============================
    if isNull(jsonData_.centerPos) then 
        jsonData_.centerPos = Vector3.zero
    end 
    if isNull(jsonData_.upDir) then 
        jsonData_.upDir = Vector3.up
    end 
    if isNull(jsonData_.forwardDir) then 
        jsonData_.forwardDir = Vector3.forward
    end 

    if isNull(jsonData_.speedMultiples) then
        jsonData_.speedMultiples = {
            yaw     = 1.0,
            pitch   = 1.0,
            zoom    = 1.0,
        }
    end

    --------
    self.jsonData = jsonData_

    -------
    --- 自由轨道相机 使用的坐标系
    self.upDir = IdolLive3D_Utils.Json2Vector3(jsonData_.upDir).normalized
    self.forwardDir = IdolLive3D_Utils.Json2Vector3(jsonData_.forwardDir).normalized
    self.rightDir = Vector3.Cross( self.upDir, self.forwardDir ).normalized
    ---
    local X = self.rightDir
    local Y = self.upDir
    local Z = self.forwardDir
    self.mtx_Local2World = Matrix4x4(
        Vector4( X.x, Y.x, Z.x, 0 ),
        Vector4( X.y, Y.y, Z.y, 0 ),
        Vector4( X.z, Y.z, Z.z, 0 ),
        Vector4( 0,   0,   0,   1 )
    ).transpose
    self.mtx_World2Local =  self.mtx_Local2World.inverse


    -- 把 jsonData_ 中所有 vcams 都装配进来:
    for i=1, table.count(jsonData_.vcamPesists) do 
        local e = jsonData_.vcamPesists[i]
        assert(e)

        table.insert( self.trackNodeParams, IdolLive3D_FreeCameraTrackNodeParams.New({ 
            fov = e.fov,
            xzDistance = e.xzDistance,
            cameraH = e.cameraH,
            pitchDegree = e.pitchDegree,
            vcamParams = e.othParams
        }))
    end 


    for i=1,#self.trackNodeParams do 
        --print("i:" .. tostring(i) .. ": " .. self.trackNodeParams[i]:ToString() )
    end 

    self.splinesGeneric = SplinesGeneric.New( 
        self.trackNodeParams,
        --SplinesGeneric.SplinesType.CatmullRom,
        SplinesGeneric.SplinesType.BSpline,
        IdolLive3D_FreeCameraTrackNodeParams.Default,
        IdolLive3D_FreeCameraTrackNodeParams.Add,
        IdolLive3D_FreeCameraTrackNodeParams.Minus,
        IdolLive3D_FreeCameraTrackNodeParams.Scale,
        IdolLive3D_FreeCameraTrackNodeParams.SetT,
        IdolLive3D_FreeCameraTrackNodeParams.GetT
    )

    ---
    self.trackNodePitchTans = {}
    for t=0.0, 1.0, 0.1 do 
        local nodeP = self:GetNodeParams(t)
        table.insert( self.trackNodePitchTans, {
            pitchTan = nodeP.cameraH / Mathf.Max( 0.001, nodeP.xzDistance ),
            t = t,
        })
    end
end


-- 需手动调用 Delete()
function IdolLive3D_FreeCameraTrackNodeParamsManager:__delete()
    for i=#self.trackNodeParams, 1, -1 do
        if isNotNull(self.trackNodeParams[i]) then
            self.trackNodeParams[i]:Delete() 
            self.trackNodeParams[i] = nil 
        end
    end
    self.trackNodeParams = nil
end


-- ===============================================================



function IdolLive3D_FreeCameraTrackNodeParamsManager:Add( vcam_ )
    table.insert( self.trackNodeParams, IdolLive3D_FreeCameraTrackNodeParams.New({ vcam = vcam_ }) )
end 

