function IdolLive3D_FreeCameraTrackNodeParamsManager:GetNodeParams( t_ )
    return self.splinesGeneric:Calculate( Mathf.Clamp01(t_) )
end



---@return IdolLive3D_FreeCameraSpatialParams
function IdolLive3D_FreeCameraTrackNodeParamsManager:FindClosestTrackNodeParams( pos_ )
    -- 直接假设 角色站在 (0,0,0)

    print("FindClosestTrackNodeParams - 未支持新功能,  施工中...")

    --- yaw:
    local yawAngle = Vector3.SignedAngle( Vector3.forward, Vector3.ProjectOnPlane(pos_, Vector3.up), Vector3.up )
    if yawAngle < 0.0 then 
        yawAngle = yawAngle + 360
    end 

    -- pitch: 
    -- todo: 已下代码假定 t=0 的点在空间中更高, t=1 更低:
    -- !! 这套实现没有照顾到 node 观察方向, 最终找到的点可能不是最适合的;
    local tgtXZDistance = Mathf.Max( 0.001, Vector2(pos_.x, pos_.z).magnitude )
    local tgtPitchTan = pos_.y / tgtXZDistance

    local pitchT = nil
    if tgtPitchTan >= self.trackNodePitchTans[1].pitchTan then 
        pitchT = self.trackNodePitchTans[1].t
    end 
    if pitchT == nil and tgtPitchTan <= self.trackNodePitchTans[#self.trackNodePitchTans].pitchTan then 
        pitchT = self.trackNodePitchTans[#self.trackNodePitchTans].t
    end 
    if pitchT == nil then
        for l=1, #self.trackNodePitchTans-1 do -- l,r 
            local lNode = self.trackNodePitchTans[l]
            local rNode = self.trackNodePitchTans[l+1]
            --printError( "l:" .. tostring(lNode.pitchTan) .. "; r:" .. tostring(rNode.pitchTan) .. "; tgt: " .. tostring(tgtPitchTan) )

            if (lNode.pitchTan<=tgtPitchTan and rNode.pitchTan>=tgtPitchTan) or (rNode.pitchTan<=tgtPitchTan and lNode.pitchTan>=tgtPitchTan) then 
                pitchT = KTool.Remap( lNode.pitchTan, rNode.pitchTan, lNode.t, rNode.t, tgtPitchTan )
                break
            end
        end
    end
    if isNull(pitchT) then 
        printError( "koko - 没找到 pitchT" )
        pitchT = 0.5
    end

    ---
    return IdolLive3D_FreeCameraSpatialParams.New(
        Mathf.Clamp( yawAngle, 0, 360 ),
        Mathf.Clamp01( Mathf.Lerp(pitchT, 0.5, 0.7) ),
        0.9 -- 手调的参数, 没有暴露给 美术编辑器
    )
end



return IdolLive3D_FreeCameraTrackNodeParamsManager
